async function run(ctx) {
  const payload = ctx.trigger.payload || {};
  ctx.tools.log('收到输入:', JSON.stringify(payload));
  const base = Number(payload.base) || 10;
  return { base: base, items: [base + 1, base + 2, base + 3] };
}

